drop policy if exists "chart_of_accounts_deny_anonymous" on public.chart_of_accounts;
create policy "chart_of_accounts_deny_anonymous" on public.chart_of_accounts as restrictive for all to authenticated using (coalesce((auth.jwt()->>'is_anonymous')::boolean,false) is false) with check (coalesce((auth.jwt()->>'is_anonymous')::boolean,false) is false);
